const API_BASE_URL = process.env.REACT_APP_API_URL || 'http://localhost:8000/api';

class ApiService {
  constructor() {
    this.baseURL = API_BASE_URL;
  }

  async request(endpoint, options = {}) {
    const url = `${this.baseURL}${endpoint}`;
    const config = {
      headers: {
        'Content-Type': 'application/json',
        ...options.headers,
      },
      ...options,
    };

    // Add CSRF token if available
    const csrfToken = this.getCSRFToken();
    if (csrfToken) {
      config.headers['X-CSRFToken'] = csrfToken;
    }

    try {
      const response = await fetch(url, config);

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        throw new Error(errorData.detail || errorData.message || `HTTP error! status: ${response.status}`);
      }

      const contentType = response.headers.get('content-type');
      if (contentType && contentType.includes('application/json')) {
        return await response.json();
      }

      return response;
    } catch (error) {
      console.error('API request failed:', error);
      throw error;
    }
  }

  getCSRFToken() {
    // Get CSRF token from cookie or meta tag
    const cookieValue = document.cookie
      .split('; ')
      .find(row => row.startsWith('csrftoken='))
      ?.split('=')[1];

    if (cookieValue) {
      return cookieValue;
    }

    const metaTag = document.querySelector('meta[name="csrf-token"]');
    return metaTag ? metaTag.getAttribute('content') : null;
  }

  // Generic CRUD methods
  async get(endpoint) {
    return this.request(endpoint, { method: 'GET' });
  }

  async post(endpoint, data) {
    return this.request(endpoint, {
      method: 'POST',
      body: JSON.stringify(data),
    });
  }

  async put(endpoint, data) {
    return this.request(endpoint, {
      method: 'PUT',
      body: JSON.stringify(data),
    });
  }

  async patch(endpoint, data) {
    return this.request(endpoint, {
      method: 'PATCH',
      body: JSON.stringify(data),
    });
  }

  async delete(endpoint) {
    return this.request(endpoint, { method: 'DELETE' });
  }

  // Domain management
  async getDomains() {
    return this.get('/domains/');
  }

  async getDomain(id) {
    return this.get(`/domains/${id}/`);
  }

  async createDomain(data) {
    return this.post('/domains/', data);
  }

  async updateDomain(id, data) {
    return this.put(`/domains/${id}/`, data);
  }

  async deleteDomain(id) {
    return this.delete(`/domains/${id}/`);
  }

  // DNS Records
  async getDNSRecords(domainId) {
    return this.get(`/dns-records/?domain=${domainId}`);
  }

  async createDNSRecord(data) {
    return this.post('/dns-records/', data);
  }

  async updateDNSRecord(id, data) {
    return this.put(`/dns-records/${id}/`, data);
  }

  async deleteDNSRecord(id) {
    return this.delete(`/dns-records/${id}/`);
  }

  // DMARC Reports
  async getDMARCReports(params = {}) {
    const queryString = new URLSearchParams(params).toString();
    return this.get(`/dmarc-reports/${queryString ? `?${queryString}` : ''}`);
  }

  async getDMARCReport(id) {
    return this.get(`/dmarc-reports/${id}/`);
  }

  async processDMARCReport(id) {
    return this.post(`/dmarc-reports/${id}/process/`);
  }

  async getDMARCStatistics(params = {}) {
    const queryString = new URLSearchParams(params).toString();
    return this.get(`/dmarc-reports/statistics/${queryString ? `?${queryString}` : ''}`);
  }

  async generateDMARCSummary(params = {}) {
    const queryString = new URLSearchParams(params).toString();
    return this.post(`/dmarc-reports/generate-summary/${queryString ? `?${queryString}` : ''}`);
  }

  // Alerts
  async getAlerts(params = {}) {
    const queryString = new URLSearchParams(params).toString();
    return this.get(`/alerts/${queryString ? `?${queryString}` : ''}`);
  }

  async getAlert(id) {
    return this.get(`/alerts/${id}/`);
  }

  async acknowledgeAlert(id) {
    return this.post(`/alerts/${id}/acknowledge/`);
  }

  async resolveAlert(id) {
    return this.post(`/alerts/${id}/resolve/`);
  }

  async getDashboardData() {
    return this.get('/alerts/dashboard/');
  }

  // Alert Rules
  async getAlertRules() {
    return this.get('/alert-rules/');
  }

  async getAlertRule(id) {
    return this.get(`/alert-rules/${id}/`);
  }

  async createAlertRule(data) {
    return this.post('/alert-rules/', data);
  }

  async updateAlertRule(id, data) {
    return this.put(`/alert-rules/${id}/`, data);
  }

  async deleteAlertRule(id) {
    return this.delete(`/alert-rules/${id}/`);
  }

  async testAlertRule(id, data) {
    return this.post(`/alert-rules/${id}/test/`, data);
  }

  // Configuration Wizard
  async getWizardProgress() {
    return this.get('/configuration-wizard/progress/');
  }

  async saveWizardStep(step, data) {
    return this.post('/configuration-wizard/save-step/', { step, data });
  }

  async resetWizard() {
    return this.post('/configuration-wizard/reset/');
  }

  // DNS Verification
  async startDNSVerification(domain = null) {
    const data = domain ? { domain } : {};
    return this.post('/dns-verification/start/', data);
  }

  async getDNSVerificationStatus(taskId) {
    return this.get(`/dns-verification/status/${taskId}/`);
  }

  // Authentication and Profile
  async getUserProfile() {
    return this.get('/auth/profile/');
  }

  async updateUserProfile(data) {
    return this.put('/auth/profile/', data);
  }

  async changePassword(data) {
    return this.post('/auth/change-password/', data);
  }

  async getCompany(id) {
    return this.get(`/auth/empresas/${id}/`);
  }

  // System Settings
  async getSystemSettings() {
    return this.get('/system-settings/');
  }

  async updateSystemSettings(data) {
    return this.post('/system-settings/', data);
  }

  // Audit Logs
  async getAuditLogs(params = {}) {
    const queryString = new URLSearchParams(params).toString();
    return this.get(`/audit-logs/${queryString ? `?${queryString}` : ''}`);
  }

  // Tags
  async getTags() {
    return this.get('/tags/');
  }

  async createTag(data) {
    return this.post('/tags/', data);
  }

  async updateTag(id, data) {
    return this.put(`/tags/${id}/`, data);
  }

  async deleteTag(id) {
    return this.delete(`/tags/${id}/`);
  }
}

// Create and export a singleton instance
const apiService = new ApiService();
export default apiService;

// Export individual methods for convenience
export const {
  getDomains,
  getDomain,
  createDomain,
  updateDomain,
  deleteDomain,
  getDNSRecords,
  createDNSRecord,
  updateDNSRecord,
  deleteDNSRecord,
  getDMARCReports,
  getDMARCReport,
  processDMARCReport,
  getDMARCStatistics,
  generateDMARCSummary,
  getAlerts,
  getAlert,
  acknowledgeAlert,
  resolveAlert,
  getDashboardData,
  getAlertRules,
  getAlertRule,
  createAlertRule,
  updateAlertRule,
  deleteAlertRule,
  testAlertRule,
  getWizardProgress,
  saveWizardStep,
  resetWizard,
  startDNSVerification,
  getDNSVerificationStatus,
  getUserProfile,
  updateUserProfile,
  changePassword,
  getCompany,
  getSystemSettings,
  updateSystemSettings,
  getAuditLogs,
  getTags,
  createTag,
  updateTag,
  deleteTag
} = apiService;
